 private static MethodNode stripRecord(MethodNode input){MethodNode copy=new MethodNode(input.access,input.name,input.desc,input.signature,input.exceptions.toArray(String[]::new));input.accept(copy);for(var instruction:copy.instructions.toArray())if(instruction instanceof MethodInsnNode call&&call.owner.equals(PredicateGetterResultRecorder.RUNTIME)&&call.name.equals("capture")&&call.desc.equals(PredicateGetterResultRecorder.DESCRIPTOR)){AbstractInsnNode id=previous(call),self=previous(id),dup=previous(self);if(!(id instanceof LdcInsnNode)||!(self instanceof VarInsnNode load&&load.getOpcode()==Opcodes.ALOAD&&load.var==0)||dup.getOpcode()!=Opcodes.DUP)throw new IllegalArgumentException();copy.instructions.remove(call);copy.instructions.remove(id);copy.instructions.remove(self);copy.instructions.remove(dup);}return copy;}
 private static boolean identity(MethodNode method){List<AbstractInsnNode>code=ops(method);return Type.getArgumentTypes(method.desc).length==0&&code.size()>=2&&code.size()<=3&&code.get(0)instanceof VarInsnNode a&&a.var==0&&a.getOpcode()==Opcodes.ALOAD&&code.getLast().getOpcode()==Opcodes.ARETURN&&(code.size()==2||code.get(1)instanceof TypeInsnNode cast&&cast.getOpcode()==Opcodes.CHECKCAST);}
 private static boolean forwarder(MethodNode method){List<AbstractInsnNode>code=ops(method);Type[]args=Type.getArgumentTypes(method.desc);if(code.size()!=args.length+3||!(code.get(0)instanceof VarInsnNode a&&a.var==0)||!(code.get(code.size()-2)instanceof MethodInsnNode call&&call.getOpcode()==Opcodes.INVOKESPECIAL&&call.itf&&call.name.equals(method.name)&&call.desc.equals(method.desc)))return false;int slot=1;for(int i=0;i<args.length;i++){if(!(code.get(i+1)instanceof VarInsnNode load&&load.var==slot&&load.getOpcode()==args[i].getOpcode(Opcodes.ILOAD)))return false;slot+=args[i].getSize();}return code.getLast().getOpcode()==Type.getReturnType(method.desc).getOpcode(Opcodes.IRETURN);}
 private static boolean fieldGetter(MethodNode method,FieldInsnNode expected){List<AbstractInsnNode>code=ops(method);return Type.getArgumentTypes(method.desc).length==0&&(code.size()==3||code.size()==4)&&code.get(0)instanceof VarInsnNode a&&a.var==0&&a.getOpcode()==Opcodes.ALOAD&&code.get(1)instanceof FieldInsnNode f&&f.getOpcode()==Opcodes.GETFIELD&&(expected==null||f.owner.equals(expected.owner)&&f.name.equals(expected.name)&&f.desc.equals(expected.desc))&&code.getLast().getOpcode()==Opcodes.ARETURN&&(code.size()==3||code.get(2)instanceof TypeInsnNode c&&c.getOpcode()==Opcodes.CHECKCAST);}
 private static String fieldOwner(FieldInsnNode field,Function<String,ClassNode>classes){Set<String>seen=new HashSet<>();for(String owner=field.owner;owner!=null&&seen.add(owner);){ClassNode node=classes.apply(owner);if(node==null)return null;for(FieldNode found:node.fields)if(found.name.equals(field.name)&&found.desc.equals(field.desc))return(found.access&Opcodes.ACC_FINAL)!=0&&(found.access&Opcodes.ACC_STATIC)==0?owner:null;owner=node.superName;}return null;}
 private static Decl resolve(Member member,Function<String,ClassNode>classes,Set<String>seen){if(!seen.add(member.owner()))return null;ClassNode owner=classes.apply(member.owner());if(owner==null)return null;MethodNode own=find(owner,member.name(),member.descriptor());if(own!=null)return new Decl(owner.name,own);if(owner.superName!=null){Decl inherited=resolve(new Member(owner.superName,member.name(),member.descriptor()),classes,seen);if(inherited!=null)return inherited;}Decl found=null;for(String iface:owner.interfaces){Decl inherited=resolve(new Member(iface,member.name(),member.descriptor()),classes,seen);if(inherited!=null){if(found!=null&&!found.equals(inherited))return null;found=inherited;}}return found;}
 private static MethodNode find(ClassNode owner,String name,String desc){return owner.methods.stream().filter(m->m.name.equals(name)&&m.desc.equals(desc)).findFirst().orElse(null);}private static MethodInsnNode unique(MethodNode method,Member member){MethodInsnNode found=null;for(var i:method.instructions)if(i instanceof MethodInsnNode call&&Member.of(call).equals(member)){if(found!=null)return null;found=call;}return found;}
 private static boolean sameBody(MethodNode a,MethodNode b){return MixinInstructionFingerprint.hash(a).equals(MixinInstructionFingerprint.hash(b));}private static List<AbstractInsnNode>ops(MethodNode method){List<AbstractInsnNode>result=new ArrayList<>();for(var i:method.instructions)if(i.getOpcode()>=0)result.add(i);return result;}private static List<AbstractInsnNode>between(AbstractInsnNode start,AbstractInsnNode end){List<AbstractInsnNode>result=new ArrayList<>();for(var i=start;i!=null&&i!=end;i=next(i))result.add(i);return result;}private static AbstractInsnNode previous(AbstractInsnNode insn){for(var i=insn.getPrevious();i!=null;i=i.getPrevious())if(i.getOpcode()>=0)return i;return null;}private static AbstractInsnNode next(AbstractInsnNode insn){for(var i=insn.getNext();i!=null;i=i.getNext())if(i.getOpcode()>=0)return i;return null;}
